'use strict';

var auth = require('@web3auth/auth');
var enums = require('../enums.js');

function createChangeProviderMiddleware({
  changeProvider
}) {
  return async ({
    request,
    context,
    next
  }) => {
    if (request.method !== enums.COMMUNICATION_JRPC_METHODS.SET_PROVIDER) {
      await next();
      return undefined;
    }
    if (!changeProvider) throw new Error("CommunicationMiddleware - opts.changeProvider not provided");
    // Propagate V2 request and context into a mutable V1-like request for handler consumption.
    const mutableRequest = auth.propagateToMutableRequest(request, context);
    const result = await changeProvider(mutableRequest);
    return result;
  };
}
function createTopupMiddleware({
  topup
}) {
  return async ({
    request,
    context,
    next
  }) => {
    if (request.method !== enums.COMMUNICATION_JRPC_METHODS.TOPUP) {
      await next();
      return undefined;
    }
    if (!topup) throw new Error("CommunicationMiddleware - opts.topup not provided");
    // Propagate V2 request and context into a mutable V1-like request for handler consumption.
    const mutableRequest = auth.propagateToMutableRequest(request, context);
    const result = await topup(mutableRequest);
    return result;
  };
}
function createSetIFrameStatusMiddleware({
  setIFrameStatus
}) {
  return async ({
    request,
    context,
    next
  }) => {
    if (request.method !== enums.COMMUNICATION_JRPC_METHODS.IFRAME_STATUS) {
      await next();
      return undefined;
    }
    if (!setIFrameStatus) throw new Error("CommunicationMiddleware - opts.setIFrameStatus not provided");
    // Propagate V2 request and context into a mutable V1-like request for handler consumption.
    const mutableRequest = auth.propagateToMutableRequest(request, context);
    const result = await setIFrameStatus(mutableRequest);
    return result;
  };
}
function createGenericJRPCMiddleware(targetMethod, handler) {
  return async ({
    request,
    context,
    next
  }) => {
    if (request.method !== targetMethod) {
      await next();
      return undefined;
    }
    if (!handler) throw new Error(`CommunicationMiddleware - ${targetMethod} not provided`);
    // Propagate V2 request and context into a mutable V1-like request for handler consumption.
    const mutableRequest = auth.propagateToMutableRequest(request, context);
    const result = await handler(mutableRequest);
    if (!result) {
      await next();
      return undefined;
    }
    return result;
  };
}
function createCommunicationMiddleware(providerHandlers) {
  const {
    getUserInfo,
    getWalletInstanceId,
    topup,
    logout,
    changeProvider,
    setIFrameStatus,
    handleWindowRpc,
    getProviderState,
    loginWithPrivateKey,
    showWalletConnect,
    showFunding,
    showCheckout,
    showReceive,
    showTransfer,
    showWalletUi,
    showSwap,
    showWindowBlockAlert,
    loginWithSessionId
  } = providerHandlers;
  const engine = auth.JRPCEngineV2.create({
    middleware: [createChangeProviderMiddleware({
      changeProvider
    }), createTopupMiddleware({
      topup
    }), createSetIFrameStatusMiddleware({
      setIFrameStatus
    }), auth.createScaffoldMiddlewareV2({
      [enums.COMMUNICATION_JRPC_METHODS.LOGOUT]: logout,
      [enums.COMMUNICATION_JRPC_METHODS.WALLET_INSTANCE_ID]: getWalletInstanceId,
      [enums.COMMUNICATION_JRPC_METHODS.USER_INFO]: getUserInfo,
      [enums.COMMUNICATION_JRPC_METHODS.CLOSED_WINDOW]: handleWindowRpc,
      [enums.COMMUNICATION_JRPC_METHODS.GET_PROVIDER_STATE]: getProviderState,
      [enums.COMMUNICATION_JRPC_METHODS.SHOW_WALLET_CONNECT]: showWalletConnect,
      [enums.COMMUNICATION_JRPC_METHODS.SHOW_FUNDING]: showFunding,
      [enums.COMMUNICATION_JRPC_METHODS.SHOW_CHECKOUT]: showCheckout,
      [enums.COMMUNICATION_JRPC_METHODS.SHOW_RECEIVE]: showReceive,
      [enums.COMMUNICATION_JRPC_METHODS.SHOW_TRANSFER]: showTransfer,
      [enums.COMMUNICATION_JRPC_METHODS.SHOW_WALLET_UI]: showWalletUi,
      [enums.COMMUNICATION_JRPC_METHODS.SHOW_SWAP]: showSwap,
      [enums.COMMUNICATION_JRPC_METHODS.WINDOW_BLOCKED]: showWindowBlockAlert
    }), createGenericJRPCMiddleware(enums.COMMUNICATION_JRPC_METHODS.LOGIN_WITH_PRIVATE_KEY, loginWithPrivateKey), createGenericJRPCMiddleware(enums.COMMUNICATION_JRPC_METHODS.LOGIN_WITH_SESSION_ID, loginWithSessionId)]
  });
  return engine.asMiddleware();
}

exports.createChangeProviderMiddleware = createChangeProviderMiddleware;
exports.createCommunicationMiddleware = createCommunicationMiddleware;
exports.createGenericJRPCMiddleware = createGenericJRPCMiddleware;
exports.createSetIFrameStatusMiddleware = createSetIFrameStatusMiddleware;
exports.createTopupMiddleware = createTopupMiddleware;
